#!/usr/bin/env python3
import http.client
import json
import os
import socket
import subprocess
import sys
import time

HOST = "127.0.0.1"
_MISSING = object()

LEAF = """
// Non-ANSI leaf in a separate virtual file.
module leaf (i, o);
  parameter P = 1;
  input  [P-1:0] i;
  output [P-1:0] o;
  assign o = i;
endmodule
"""

TOP = """
/* ANSI top: parameters propagate through named and positional instances. */
module top #(
  parameter W = 4,
  parameter SCALE = W + 1
) (
  input  wire [W-1:0] a,
  output wire [W-1:0] y,
  output wire [1:0] pair
);
  localparam L = (W + SCALE) >> 1;
  wire signed [W-1:0] t;
  wire [W-1:0] n1;
  wire [W-1:0] n2;
  reg [1:0] saved;
  assign t = a[W-1:0];
  assign y = n1;
  assign pair = {a[0], a[W-1]};
  leaf #(.P(W)) u_named (.i(t), .o(n1));
  leaf #(W) u_pos (a, n2);
  leaf #(.P(W)) u_open (.i(a), .o());
endmodule
"""

HAPPY = {
    "sources": {"virtual/leaf.v": LEAF, "virtual/top.v": TOP},
    "top": "top",
    "parameters": {"W": "2 + 4"},
}


def request(port, method, path, payload=_MISSING, raw=None):
    headers = {}
    body = None
    if raw is not None:
        body = raw if isinstance(raw, bytes) else raw.encode("utf-8")
        headers["Content-Type"] = "application/json"
    elif payload is not _MISSING:
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        headers["Content-Type"] = "application/json"
    conn = http.client.HTTPConnection(HOST, int(port), timeout=5)
    conn.request(method, path, body=body, headers=headers)
    response = conn.getresponse()
    data = response.read().decode("utf-8", "replace")
    status = response.status
    conn.close()
    try:
        parsed = json.loads(data) if data else None
    except json.JSONDecodeError:
        parsed = None
    return status, parsed, data


def product_env():
    env = os.environ.copy()
    old = env.get("PYTHONPATH")
    env["PYTHONPATH"] = "src" + (os.pathsep + old if old else "")
    return env


def serve(port):
    argv = [sys.executable, "-m", "siliconrail.server", "--host", HOST, "--port", str(port)]
    os.execvpe(sys.executable, argv, product_env())


def free_port():
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.bind((HOST, 0))
    port = sock.getsockname()[1]
    sock.close()
    return port


def wait_ready(port, proc):
    deadline = time.time() + 10
    last = None
    while time.time() < deadline:
        if proc.poll() is not None:
            out, err = proc.communicate(timeout=1)
            raise RuntimeError("service exited before readiness\nstdout: %s\nstderr: %s" % (out, err))
        try:
            status, body, _ = request(port, "GET", "/healthz")
            if status == 200 and isinstance(body, dict):
                return
            last = "HTTP %s %r" % (status, body)
        except Exception as exc:
            last = repr(exc)
        time.sleep(0.1)
    raise RuntimeError("service did not become ready: %s" % last)


def root_node(body):
    if isinstance(body, dict) and isinstance(body.get("hierarchy"), dict):
        return body["hierarchy"]
    return body


def child_nodes(node):
    value = node.get("children")
    if value is None:
        value = node.get("instances")
    return value


def child_name(node):
    value = node.get("instance_name")
    if value is None:
        value = node.get("instance")
    return value


def child_path(node):
    value = node.get("instance_path")
    if value is None:
        value = node.get("path")
    return value


def connections(node):
    value = node.get("connections_from_parent")
    if value is None:
        value = node.get("connections")
    return value


def assignments(node):
    value = node.get("continuous_assignments")
    if value is None:
        value = node.get("assigns")
    return value


def numeric(value):
    if isinstance(value, bool):
        raise ValueError("boolean is not an integer result")
    return int(value)


def parameter_map(node):
    return {item["name"]: numeric(item["value"]) for item in node["parameters"]}


def expression_has(value, marker):
    if isinstance(value, dict):
        if value.get("kind") == marker or value.get("expr") == marker:
            return True
        return any(expression_has(item, marker) for item in value.values())
    if isinstance(value, list):
        return any(expression_has(item, marker) for item in value)
    return False


def error_code(body):
    if not isinstance(body, dict) or not isinstance(body.get("error"), dict):
        return None
    return body["error"].get("code")


def error_location(body):
    error = body.get("error", {}) if isinstance(body, dict) else {}
    loc = error.get("location")
    return loc if isinstance(loc, dict) else error


class Suite:
    def __init__(self):
        self.failures = []
        self.passes = 0

    def check(self, label, condition, actual=None, expected=None):
        if condition:
            self.passes += 1
            print("PASS", label)
        else:
            detail = "%s: expected %r, got %r" % (label, expected, actual)
            self.failures.append(detail)
            print("FAIL", detail)

    def equal(self, label, actual, expected):
        self.check(label, actual == expected, actual, expected)


def expect_error(suite, port, label, payload, status_expected, codes):
    status, body, _ = request(port, "POST", "/v1/rtl/elaborate", payload=payload)
    allowed = {codes} if isinstance(codes, str) else set(codes)
    suite.equal(label + " status", status, status_expected)
    suite.check(label + " code", error_code(body) in allowed, error_code(body), sorted(allowed))
    message = body.get("error", {}).get("message") if isinstance(body, dict) else None
    suite.check(label + " stable message shape", isinstance(message, str) and bool(message), message, "non-empty string")
    print("  response", json.dumps(body, sort_keys=True))
    return status, body


def run_checks(port):
    suite = Suite()

    status, health, _ = request(port, "GET", "/healthz")
    suite.equal("health status", status, 200)
    suite.check("health JSON object", isinstance(health, dict), health, "object")
    if isinstance(health, dict):
        suite.equal("health state", health.get("status"), "ok")
        suite.equal("health service", health.get("service"), "siliconrail")
        suite.check("health version retained", "version" in health, health, "version field")

    status, missing_route, _ = request(port, "GET", "/route-that-does-not-exist")
    suite.equal("unknown route status", status, 404)
    suite.equal("unknown route code", error_code(missing_route), "not_found")

    status, body, raw_first = request(port, "POST", "/v1/rtl/elaborate", payload=HAPPY)
    suite.equal("cross-file elaboration status", status, 200)
    if status == 200 and isinstance(body, dict):
        try:
            top = root_node(body)
            suite.equal("top module", top.get("module"), "top")
            params = parameter_map(top)
            suite.equal("top override W", params.get("W"), 6)
            suite.equal("dependent parameter SCALE", params.get("SCALE"), 7)
            suite.equal("localparam L", params.get("L"), 6)

            ports = {item["name"]: item for item in top["ports"]}
            suite.equal("ANSI input direction", ports["a"].get("direction"), "input")
            suite.equal("input width", ports["a"].get("width"), 6)
            suite.equal("output width", ports["y"].get("width"), 6)

            nets = {item["name"]: item for item in top["nets"]}
            suite.equal("signed net retained", nets["t"].get("signed"), True)
            suite.equal("reg declaration retained", nets["saved"].get("type", nets["saved"].get("kind")), "reg")
            suite.equal("net final width", nets["t"].get("width"), 6)

            children = {child_name(item): item for item in child_nodes(top)}
            suite.equal("complete instance names", set(children), {"u_named", "u_pos", "u_open"})
            for name in ("u_named", "u_pos", "u_open"):
                child = children[name]
                suite.equal(name + " module type", child.get("module"), "leaf")
                suite.equal(name + " expanded P", parameter_map(child).get("P"), 6)
                suite.equal(name + " full path", child_path(child), ["top", name])
                child_ports = {item["name"]: item for item in child["ports"]}
                suite.equal(name + " leaf port width", child_ports["i"].get("width"), 6)
            open_connections = {item["port"]: item for item in connections(children["u_open"])}
            suite.equal("unconnected port explicit flag", open_connections["o"].get("connected"), False)
            expression = open_connections["o"].get("expression", open_connections["o"].get("expr"))
            suite.equal("unconnected port expression", expression, None)
            suite.check("continuous assignments exposed", len(assignments(top)) >= 3, len(assignments(top)), ">= 3")
            suite.check("concatenation expression exposed", expression_has(assignments(top), "concat"), assignments(top), "concat expression")
        except Exception as exc:
            suite.check("successful IR has complete documented structure", False, repr(exc), "documented IR fields")

    reversed_request = {
        "sources": {"virtual/top.v": TOP, "virtual/leaf.v": LEAF},
        "top": "top",
        "parameters": {"W": "2 + 4"},
    }
    status2, _, raw_second = request(port, "POST", "/v1/rtl/elaborate", payload=HAPPY)
    status3, _, raw_reversed = request(port, "POST", "/v1/rtl/elaborate", payload=reversed_request)
    suite.equal("repeat status", status2, 200)
    suite.equal("reordered sources status", status3, 200)
    suite.equal("repeated serialization deterministic", raw_second, raw_first)
    suite.equal("source member order serialization deterministic", raw_reversed, raw_first)

    ascending = {
        "sources": {"ascending.v": "module top(input [0:3] a, output [1:2] y); assign y = a[1:2]; endmodule"},
        "top": "top",
    }
    status, ascending_body, _ = request(port, "POST", "/v1/rtl/elaborate", payload=ascending)
    suite.equal("ascending range status", status, 200)
    if status == 200:
        try:
            ascending_ports = {item["name"]: item for item in root_node(ascending_body)["ports"]}
            suite.equal("ascending input width", ascending_ports["a"].get("width"), 4)
            suite.equal("ascending slice width", ascending_ports["y"].get("width"), 2)
        except Exception as exc:
            suite.check("ascending range IR readable", False, repr(exc), "ports with widths")

    status, bad_json, _ = request(port, "POST", "/v1/rtl/elaborate", raw=b"{not-json")
    suite.equal("malformed JSON status", status, 400)
    suite.equal("malformed JSON code", error_code(bad_json), "invalid_request")

    expect_error(suite, port, "missing top", {"sources": {"a.v": "module a; endmodule"}}, 400, "invalid_request")
    expect_error(suite, port, "wrong sources type", {"sources": [], "top": "top"}, 400, "invalid_request")
    expect_error(suite, port, "bad top parameter expression", {"sources": {"a.v": "module top #(parameter P=1)(); endmodule"}, "top": "top", "parameters": {"P": "1 +"}}, 400, "invalid_request")
    expect_error(suite, port, "null parameters type", {"sources": {"a.v": "module top; endmodule"}, "top": "top", "parameters": None}, 400, "invalid_request")
    expect_error(suite, port, "unexpected request field", {"sources": {"a.v": "module top; endmodule"}, "top": "top", "extra": True}, 400, "invalid_request")

    syntax_request = {"sources": {"syntax.v": "module top ( ; endmodule"}, "top": "top"}
    _, syntax_body = expect_error(suite, port, "syntax diagnostic", syntax_request, 422, "verilog_syntax_error")
    syntax_loc = error_location(syntax_body)
    suite.equal("syntax virtual filename", syntax_loc.get("file"), "syntax.v")
    suite.check("syntax line is positive", isinstance(syntax_loc.get("line"), int) and syntax_loc["line"] >= 1, syntax_loc, "positive line")
    suite.check("syntax column is positive", isinstance(syntax_loc.get("column"), int) and syntax_loc["column"] >= 1, syntax_loc, "positive column")
    _, syntax_body_again, _ = request(port, "POST", "/v1/rtl/elaborate", payload=syntax_request)
    suite.equal("syntax diagnostic stable across calls", syntax_body_again, syntax_body)

    expect_error(suite, port, "unknown top", {"sources": {"a.v": "module known; endmodule"}, "top": "missing"}, 422, "unknown_top")
    _, unknown_body = expect_error(suite, port, "unknown module", {"sources": {"a.v": "module top; absent u(); endmodule"}, "top": "top"}, 422, "unknown_module")
    suite.equal("semantic diagnostic filename", error_location(unknown_body).get("file"), "a.v")
    expect_error(suite, port, "missing parameter target", {"sources": {"a.v": "module top; leaf #(.NOPE(2)) u(); endmodule module leaf #(parameter P=1)(); endmodule"}, "top": "top"}, 422, "parameter_error")
    expect_error(suite, port, "hierarchy cycle", {"sources": {"a.v": "module a; b u(); endmodule", "b.v": "module b; a u(); endmodule"}, "top": "a"}, 422, "hierarchy_cycle")
    expect_error(suite, port, "duplicate declaration", {"sources": {"a.v": "module top; wire x; wire x; endmodule"}, "top": "top"}, 422, "duplicate_name")
    expect_error(suite, port, "duplicate module definition", {"sources": {"a.v": "module top; endmodule", "b.v": "module top; endmodule"}, "top": "top"}, 422, "duplicate_name")
    expect_error(suite, port, "connection width", {"sources": {"a.v": "module leaf(input [3:0] i); endmodule module top; wire [1:0] n; leaf u(.i(n)); endmodule"}, "top": "top"}, 422, "connection_error")
    expect_error(suite, port, "unknown named port", {"sources": {"a.v": "module leaf(input i); endmodule module top; wire n; leaf u(.missing(n)); endmodule"}, "top": "top"}, 422, "connection_error")
    expect_error(suite, port, "positional port count", {"sources": {"a.v": "module leaf(input i, output o); endmodule module top; wire n; leaf u(n); endmodule"}, "top": "top"}, 422, "connection_error")
    expect_error(suite, port, "unsupported construct", {"sources": {"a.v": "module top; initial begin end endmodule"}, "top": "top"}, 422, "unsupported_construct")

    cross_problem = {
        "sources": {
            "a.v": "module top; absent u(); endmodule",
            "z.v": "module broken ( ; endmodule",
        },
        "top": "top",
    }
    _, cross_body = expect_error(suite, port, "cross-file first diagnostic", cross_problem, 422, "unknown_module")
    suite.equal("cross-file first filename", error_location(cross_body).get("file"), "a.v")

    duplicate_override = {
        "sources": {"a.v": "module leaf #(parameter P=1)(); endmodule module top; leaf #(.P(1), .P(2)) u(); endmodule"},
        "top": "top",
    }
    expect_error(suite, port, "duplicate named parameter override", duplicate_override, 422, "duplicate_name")

    out_of_range = {
        "sources": {"a.v": "module top(input [3:0] a, output y); assign y = a[4]; endmodule"},
        "top": "top",
    }
    expect_error(suite, port, "out-of-range bit select", out_of_range, 422, {"connection_error", "unsupported_construct"})

    constant_request = {
        "sources": {"constants.v": "module top #(parameter X=6^3, parameter S=4'h1f, parameter N=-3)(); endmodule"},
        "top": "top",
    }
    status, constant_body, _ = request(port, "POST", "/v1/rtl/elaborate", payload=constant_request)
    suite.equal("constant expression request status", status, 200)
    if status == 200:
        try:
            values = parameter_map(root_node(constant_body))
            suite.equal("bitwise XOR value", values.get("X"), 5)
            suite.equal("explicit-width literal truncation", values.get("S"), 15)
            suite.equal("negative integer parameter", values.get("N"), -3)
        except Exception as exc:
            suite.check("constant parameter IR readable", False, repr(exc), "parameter list")

    print("SUMMARY passes=%d failures=%d" % (suite.passes, len(suite.failures)))
    for failure in suite.failures:
        print("  -", failure)
    return 1 if suite.failures else 0


def compact_observation(port, label, payload, expected):
    status, body, _ = request(port, "POST", "/v1/rtl/elaborate", payload=payload)
    print("\n[%s]" % label)
    print("expected:", expected)
    print("actual status/code:", status, error_code(body))
    if status == 200 and label == "constant expression semantics":
        try:
            print("actual parameters:", json.dumps(parameter_map(root_node(body)), sort_keys=True))
        except Exception:
            print("actual body:", json.dumps(body, sort_keys=True))
    else:
        print("actual body:", json.dumps(body, sort_keys=True))


def demo_core(port):
    print("=== In-memory cross-file Verilog elaboration ===")
    print("request: top=top, W='2 + 4', files=virtual/leaf.v and virtual/top.v")
    status, body, _ = request(port, "POST", "/v1/rtl/elaborate", payload=HAPPY)
    print("actual HTTP status:", status)
    print(json.dumps(body, indent=2, sort_keys=True))
    return 0


def demo_boundary(port):
    print("=== Public boundary reproduction ===")
    compact_observation(
        port,
        "constant expression semantics",
        {"sources": {"constants.v": "module top #(parameter X=6^3, parameter S=4'h1f, parameter N=-3)(); endmodule"}, "top": "top"},
        "HTTP 200 with X=5, S=15, N=-3",
    )
    compact_observation(
        port,
        "first diagnostic across files and phases",
        {"sources": {"a.v": "module top; absent u(); endmodule", "z.v": "module broken ( ; endmodule"}, "top": "top"},
        "HTTP 422 unknown_module located in a.v",
    )
    return 0


def checked_main():
    port = free_port()
    argv = [sys.executable, "-m", "siliconrail.server", "--host", HOST, "--port", str(port)]
    proc = subprocess.Popen(argv, env=product_env(), stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    try:
        wait_ready(port, proc)
        print("service ready on", port)
        return run_checks(port)
    finally:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=3)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait(timeout=3)


def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else "check"
    if mode == "serve":
        if len(sys.argv) != 3:
            raise SystemExit("usage: rtl_acceptance.py serve PORT")
        serve(int(sys.argv[2]))
        return 0
    if mode == "demo-core":
        if len(sys.argv) != 3:
            raise SystemExit("usage: rtl_acceptance.py demo-core PORT")
        return demo_core(int(sys.argv[2]))
    if mode == "demo-boundary":
        if len(sys.argv) != 3:
            raise SystemExit("usage: rtl_acceptance.py demo-boundary PORT")
        return demo_boundary(int(sys.argv[2]))
    if mode == "check":
        return checked_main()
    raise SystemExit("unknown mode: " + mode)


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        raise SystemExit(130)
    except Exception as exc:
        print("FATAL", type(exc).__name__, str(exc), file=sys.stderr)
        raise SystemExit(2)

"""Verilog-2001 combinational-subset parser producing a JSON-safe circuit IR.

Supported subset (per source text, multiple modules allowed):

- case-sensitive identifiers, line (``//``) and block (``/* */``) comments
- decimal constants and sized binary/hex constants (``42``, ``4'b1010``, ``8'hFF``)
- ANSI-style ``input``/``output``/``inout`` port declarations
- ``wire`` declarations and continuous ``assign`` statements
- expressions: parentheses, bit-select, constant-range part-select,
  concatenation, and common unary/binary operators

All parse failures raise :class:`RTLParseError` with a stable ``code`` and a
1-based ``line``/``column``.
"""

from __future__ import annotations

import string


class RTLParseError(Exception):
    """Public parse failure.

    Carries ``code`` (machine-readable category), 1-based ``line`` and
    ``column``, and a non-empty human-readable ``message``.
    """

    def __init__(self, code: str, message: str, line: int, column: int) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.line = line
        self.column = column


# ---------------------------------------------------------------------------
# Lexer
# ---------------------------------------------------------------------------

_IDENT_START = set(string.ascii_letters) | {"_"}
_IDENT_CHAR = _IDENT_START | set(string.digits) | {"$"}

_MULTI_OPS = (
    "<<", ">>", "<=", ">=", "==", "!=", "&&", "||", "~&", "~|", "~^", "^~", "**",
)
_SINGLE_PUNCT = set("()[]{},;:=+-*/%&|^~!<>#")


class _Token:
    __slots__ = ("kind", "text", "line", "column", "number")

    def __init__(self, kind: str, text: str, line: int, column: int, number=None) -> None:
        self.kind = kind  # "ident" | "number" | "punct" | "eof"
        self.text = text
        self.line = line
        self.column = column
        self.number = number  # (value, width) for number tokens, else None


def _describe(tok: _Token) -> str:
    if tok.kind == "eof":
        return "end of input"
    return repr(tok.text)


class _Lexer:
    """Lazy tokenizer: tokens are produced on demand so the parser can
    classify an earlier construct (e.g. ``always``) before the lexer ever
    reaches a later illegal character."""

    def __init__(self, source: str) -> None:
        self.source = source
        self.i = 0
        self.line = 1
        self.col = 1

    def _error(self, message: str, line: int, col: int) -> None:
        raise RTLParseError("syntax_error", message, line, col)

    def next_token(self) -> _Token:
        source, n = self.source, len(self.source)
        while self.i < n:
            ch = source[self.i]
            if ch in " \t\r":
                self.i += 1
                self.col += 1
                continue
            if ch == "\n":
                self.i += 1
                self.line += 1
                self.col = 1
                continue
            if source.startswith("//", self.i):
                j = source.find("\n", self.i)
                if j == -1:
                    self.i = n
                    break
                self.i = j
                continue
            if source.startswith("/*", self.i):
                start_line, start_col = self.line, self.col
                j = source.find("*/", self.i + 2)
                if j == -1:
                    self._error("unterminated block comment", start_line, start_col)
                segment = source[self.i:j + 2]
                self.line += segment.count("\n")
                if "\n" in segment:
                    self.col = len(segment) - segment.rindex("\n")
                else:
                    self.col += len(segment)
                self.i = j + 2
                continue
            if ch in _IDENT_START:
                j = self.i
                while j < n and source[j] in _IDENT_CHAR:
                    j += 1
                tok = _Token("ident", source[self.i:j], self.line, self.col)
                self.col += j - self.i
                self.i = j
                return tok
            if ch.isdigit():
                return self._lex_number()
            two = source[self.i:self.i + 2]
            if two in _MULTI_OPS:
                tok = _Token("punct", two, self.line, self.col)
                self.i += 2
                self.col += 2
                return tok
            if ch in _SINGLE_PUNCT:
                tok = _Token("punct", ch, self.line, self.col)
                self.i += 1
                self.col += 1
                return tok
            self._error(f"unexpected character {ch!r}", self.line, self.col)
        return _Token("eof", "", self.line, self.col)

    def _lex_number(self) -> _Token:
        source, n = self.source, len(self.source)
        i, line, col = self.i, self.line, self.col
        j = i
        while j < n and (source[j].isdigit() or source[j] == "_"):
            j += 1
        size_text = source[i:j].replace("_", "")

        if j < n and source[j] == "'":
            if j + 1 >= n or source[j + 1] not in "bBhH":
                self._error("sized literal must use base 'b' or 'h'", line, col)
            base_ch = source[j + 1].lower()
            valid = "01_" if base_ch == "b" else "0123456789abcdefABCDEF_"
            k = j + 2
            while k < n and source[k] in valid:
                k += 1
            digit_text = source[j + 2:k].replace("_", "")
            if not digit_text:
                self._error("sized literal has no digits", line, col)
            if k < n and (source[k].isalnum() or source[k] in "_$?"):
                self._error(f"invalid digit in {base_ch!r}-based literal", line, col)
            width = int(size_text)
            value = int(digit_text, 2 if base_ch == "b" else 16)
            self.i = k
            self.col += k - i
            return _Token("number", source[i:k], line, col, (value, width))

        if j < n and (source[j].isalpha() or source[j] in "_$"):
            self._error("invalid decimal literal", line, col)
        self.i = j
        self.col += j - i
        return _Token("number", source[i:j], line, col, (int(size_text), None))


# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------

_DIRECTIONS = ("input", "output", "inout")
_CORE_KEYWORDS = {"module", "endmodule", "wire", "assign"}
_UNSUPPORTED_KEYWORDS = {
    "always", "initial", "reg", "parameter", "localparam", "integer", "genvar",
    "function", "endfunction", "task", "endtask", "generate", "endgenerate",
    "for", "while", "repeat", "forever", "begin", "end", "if", "else",
    "case", "casex", "casez", "posedge", "negedge", "signed", "unsigned",
    "real", "realtime", "time", "tri", "wand", "wor", "supply0", "supply1",
    "defparam", "specify", "endspecify", "primitive", "endprimitive",
}
_ALL_KEYWORDS = _CORE_KEYWORDS | _UNSUPPORTED_KEYWORDS | set(_DIRECTIONS)

_BINARY_PREC = {
    "||": 1,
    "&&": 2,
    "|": 3,
    "^": 4, "~^": 4, "^~": 4,
    "&": 5,
    "==": 6, "!=": 6,
    "<": 7, "<=": 7, ">": 7, ">=": 7,
    "<<": 8, ">>": 8,
    "+": 9, "-": 9,
    "*": 10, "/": 10, "%": 10,
    "**": 11,
}
_RIGHT_ASSOC = {"**"}
_UNARY_OPS = {"+", "-", "~", "!", "&", "|", "^", "~&", "~|", "~^", "^~"}


class _Parser:
    def __init__(self, lexer: _Lexer) -> None:
        self.lexer = lexer
        self.current = lexer.next_token()

    # -- token helpers -----------------------------------------------------

    def peek(self) -> _Token:
        return self.current

    def advance(self) -> _Token:
        tok = self.current
        if tok.kind != "eof":
            self.current = self.lexer.next_token()
        return tok

    def error(self, code: str, message: str, tok: _Token | None = None) -> None:
        tok = tok if tok is not None else self.peek()
        raise RTLParseError(code, message, tok.line, tok.column)

    def at_punct(self, text: str) -> bool:
        tok = self.peek()
        return tok.kind == "punct" and tok.text == text

    def at_ident(self, text: str) -> bool:
        tok = self.peek()
        return tok.kind == "ident" and tok.text == text

    def expect_punct(self, text: str) -> _Token:
        tok = self.peek()
        if tok.kind != "punct" or tok.text != text:
            self.error("syntax_error", f"expected {text!r} but found {_describe(tok)}")
        return self.advance()

    def expect_name(self, what: str) -> _Token:
        tok = self.peek()
        if tok.kind != "ident" or tok.text in _ALL_KEYWORDS:
            self.error("syntax_error", f"expected {what} but found {_describe(tok)}")
        return self.advance()

    # -- top level ---------------------------------------------------------

    def parse(self) -> dict:
        modules = []
        module_names: set[str] = set()
        while self.peek().kind != "eof":
            modules.append(self.parse_module(module_names))
        if not modules:
            self.error("syntax_error", "source contains no module")
        return {"modules": modules}

    def parse_module(self, module_names: set[str]) -> dict:
        if not self.at_ident("module"):
            self.error("syntax_error", f"expected 'module' but found {_describe(self.peek())}")
        self.advance()
        name_tok = self.expect_name("module name")
        if name_tok.text in module_names:
            self.error("duplicate_name", f"duplicate module name {name_tok.text!r}", name_tok)
        module_names.add(name_tok.text)
        if self.at_punct("#"):
            self.error("unsupported_construct", "parameterized module headers are not supported")
        self.expect_punct("(")

        ports: list[dict] = []
        declared: set[str] = set()
        if not self.at_punct(")"):
            self.parse_port_list(ports, declared)
        self.expect_punct(")")
        self.expect_punct(";")

        nets: list[dict] = []
        assigns: list[dict] = []
        refs: list[tuple[str, _Token]] = []
        while not self.at_ident("endmodule"):
            tok = self.peek()
            if tok.kind == "eof":
                self.error("syntax_error", "unexpected end of input inside module")
            if tok.kind == "ident" and tok.text == "wire":
                self.advance()
                self.parse_net_decl(nets, declared)
            elif tok.kind == "ident" and tok.text == "assign":
                self.advance()
                assigns.append(self.parse_assign(refs))
            elif tok.kind == "ident" and tok.text in _UNSUPPORTED_KEYWORDS:
                self.error("unsupported_construct", f"construct {tok.text!r} is not supported")
            elif tok.kind == "ident":
                self.error(
                    "unsupported_construct",
                    f"module item starting with {tok.text!r} is not supported "
                    "(instances and procedural blocks are outside the subset)",
                )
            elif tok.kind == "punct" and tok.text == "#":
                self.error("unsupported_construct", "parameter syntax is not supported")
            else:
                self.error("syntax_error", f"unexpected {_describe(tok)} inside module")
        self.advance()  # consume 'endmodule'

        for name, tok in refs:
            if name not in declared:
                self.error("undeclared_signal", f"signal {name!r} is not declared in this module", tok)

        return {"name": name_tok.text, "ports": ports, "nets": nets, "assigns": assigns}

    # -- declarations --------------------------------------------------------

    def _declare(self, declared: set[str], name_tok: _Token) -> None:
        if name_tok.text in declared:
            self.error("duplicate_name", f"duplicate port/net name {name_tok.text!r}", name_tok)
        declared.add(name_tok.text)

    def parse_port_list(self, ports: list[dict], declared: set[str]) -> None:
        while True:
            tok = self.peek()
            if tok.kind == "ident" and tok.text in _DIRECTIONS:
                direction = tok.text
                self.advance()
            elif tok.kind == "ident":
                self.error("unsupported_construct", "non-ANSI port declarations are not supported")
            else:
                self.error("syntax_error", f"expected port direction but found {_describe(tok)}")
            width = self.parse_optional_range()
            while True:
                if self.peek().kind == "ident" and self.peek().text in _UNSUPPORTED_KEYWORDS:
                    self.error("unsupported_construct", f"port kind {self.peek().text!r} is not supported")
                name_tok = self.expect_name("port name")
                self._declare(declared, name_tok)
                ports.append({"name": name_tok.text, "direction": direction, "width": width})
                if not self.at_punct(","):
                    return
                self.advance()
                if self.at_ident(_DIRECTIONS[0]) or self.at_ident(_DIRECTIONS[1]) or self.at_ident(_DIRECTIONS[2]):
                    break  # a new direction group follows

    def parse_net_decl(self, nets: list[dict], declared: set[str]) -> None:
        width = self.parse_optional_range()
        while True:
            name_tok = self.expect_name("net name")
            self._declare(declared, name_tok)
            nets.append({"name": name_tok.text, "width": width})
            if not self.at_punct(","):
                break
            self.advance()
        self.expect_punct(";")

    def parse_optional_range(self) -> int:
        if not self.at_punct("["):
            return 1
        self.advance()
        msb = self.parse_range_endpoint()
        self.expect_punct(":")
        lsb = self.parse_range_endpoint()
        self.expect_punct("]")
        return abs(msb - lsb) + 1

    def parse_range_endpoint(self) -> int:
        tok = self.peek()
        if tok.kind != "number" or tok.number[1] is not None:
            self.error("invalid_range", "range endpoint must be a non-negative decimal constant")
        self.advance()
        return tok.number[0]

    # -- statements ----------------------------------------------------------

    def parse_assign(self, refs: list[tuple[str, _Token]]) -> dict:
        target = self.parse_expr(refs)
        self.expect_punct("=")
        value = self.parse_expr(refs)
        self.expect_punct(";")
        return {"target": target, "value": value}

    # -- expressions ---------------------------------------------------------

    def parse_expr(self, refs: list[tuple[str, _Token]], min_prec: int = 1) -> dict:
        left = self.parse_unary(refs)
        while True:
            tok = self.peek()
            if tok.kind != "punct":
                break
            prec = _BINARY_PREC.get(tok.text)
            if prec is None or prec < min_prec:
                break
            self.advance()
            next_min = prec if tok.text in _RIGHT_ASSOC else prec + 1
            right = self.parse_expr(refs, next_min)
            left = {"kind": "binary", "op": tok.text, "left": left, "right": right}
        return left

    def parse_unary(self, refs: list[tuple[str, _Token]]) -> dict:
        tok = self.peek()
        if tok.kind == "punct" and tok.text in _UNARY_OPS:
            self.advance()
            operand = self.parse_unary(refs)
            return {"kind": "unary", "op": tok.text, "operand": operand}
        return self.parse_postfix(refs)

    def parse_postfix(self, refs: list[tuple[str, _Token]]) -> dict:
        node = self.parse_primary(refs)
        while self.at_punct("["):
            start = self.advance()
            first = self.parse_expr(refs)
            if self.at_punct(":"):
                self.advance()
                second = self.parse_expr(refs)
                self.expect_punct("]")
                msb = self._const_endpoint(first, start)
                lsb = self._const_endpoint(second, start)
                node = {"kind": "range_select", "base": node, "msb": msb, "lsb": lsb}
            else:
                self.expect_punct("]")
                node = {"kind": "bit_select", "base": node, "index": first}
        return node

    def _const_endpoint(self, node: dict, tok: _Token) -> int:
        if node["kind"] != "const" or node["width"] is not None or node["value"] < 0:
            self.error("invalid_range", "range select endpoints must be non-negative decimal constants", tok)
        return node["value"]

    def parse_primary(self, refs: list[tuple[str, _Token]]) -> dict:
        tok = self.peek()
        if tok.kind == "number":
            self.advance()
            value, width = tok.number
            return {"kind": "const", "value": value, "width": width}
        if tok.kind == "ident":
            if tok.text in _ALL_KEYWORDS:
                self.error("syntax_error", f"unexpected keyword {tok.text!r} in expression")
            self.advance()
            refs.append((tok.text, tok))
            return {"kind": "ref", "name": tok.text}
        if tok.kind == "punct" and tok.text == "(":
            self.advance()
            node = self.parse_expr(refs)
            self.expect_punct(")")
            return node
        if tok.kind == "punct" and tok.text == "{":
            self.advance()
            items = [self.parse_expr(refs)]
            while self.at_punct(","):
                self.advance()
                items.append(self.parse_expr(refs))
            self.expect_punct("}")
            return {"kind": "concat", "items": items}
        self.error("syntax_error", f"expected expression but found {_describe(tok)}")


def parse(source: str) -> dict:
    """Parse Verilog source text into a JSON-serializable circuit IR."""
    return _Parser(_Lexer(source)).parse()

"""HTTP entry point for SiliconRail."""

from __future__ import annotations

import argparse
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .rtl import RTLParseError
from .service import Service


def env_address() -> tuple[str, int]:
    raw = os.environ.get("SILICONRAIL_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid SILICONRAIL_ADDR: {raw!r}")
    return host, int(port)


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: dict) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def do_POST(self) -> None:
        if self.path != "/v1/rtl/parse":
            self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})
            return
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            payload = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self.send_json(400, {"error": {"code": "invalid_request", "message": "body must be a JSON object with a string 'source'"}})
            return
        if not isinstance(payload, dict) or not isinstance(payload.get("source"), str):
            self.send_json(400, {"error": {"code": "invalid_request", "message": "body must be a JSON object with a string 'source'"}})
            return
        try:
            ir = self.service.parse_rtl(payload["source"])
        except RTLParseError as exc:
            self.send_json(422, {"error": {"code": exc.code, "line": exc.line, "column": exc.column, "message": exc.message}})
            return
        self.send_json(200, ir)

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="siliconrail.server", description="芯片前端设计与 RTL 流程工具链")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"SiliconRail listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

